import React from'react';import{createRoot}from'react-dom/client';import{MemoryRouter,Routes,Route,Outlet}from'react-router-dom';
import i18n from'../../../src/i18n/config';import{DocumentComparePage}from'../../../src/features/document-compare/DocumentComparePage';import{DocumentCompareResultPage}from'../../../src/features/document-compare/DocumentCompareResultPage';import{DocumentCompareSessionProvider,useDocumentCompareSession}from'../../../src/features/document-compare/documentCompareSession';
import'../../../src/styles/tailwind.css';import'../../../src/styles/global.css';import'../../../src/styles/worklazy-theme.css';
function Probe(){const session=useDocumentCompareSession();Object.assign(window,{getDocumentResultsForTest:()=>session.results});return<Outlet/>;}
const language=new URLSearchParams(location.search).get('lang')==='ko'?'ko':'en';void i18n.changeLanguage(language).then(()=>createRoot(document.getElementById('root')!).render(<MemoryRouter initialEntries={[`/${language}/tools/document-compare`]}><Routes><Route path="/:lang/tools/document-compare" element={<DocumentCompareSessionProvider/>}><Route element={<Probe/>}><Route index element={<DocumentComparePage/>}/><Route path="results/:pairNumber" element={<DocumentCompareResultPage/>}/></Route></Route></Routes></MemoryRouter>));
